    changes: [tables, { field: 'starts_at_local', from: null, to: r.starts_at_local }, { field: 'party_size', from: null, to: r.party_size }],
  };
  return r.status === 'cancelled' ? [created, { ...base, seq: 2, event: 'cancelled', changes: [] }] : [created];
